#pragma once
static void checkCatalyticV2(App& app,const std::string& dir){
 using namespace studio::catalytic;auto require=[](bool ok,const std::string& why){if(!ok)throw std::runtime_error("catalytic v2: "+why);};int cases=0;
 for(int n=0;n<2;++n)for(int format=0;format<4;++format)for(bool excited:{false,true})for(bool collapsed:{false,true}){
    CatalyticMetal cfg;cfg.numerals=n;cfg.format=format;cfg.excited=excited;cfg.collapsed=collapsed;Session sample;sample.doc.setDefaultFont("Arial");sample.doc.setDefaultBondLength(22);auto id=cfg.apply(sample.doc,kInvalidObjectId,Vec2());auto text=sample.doc.atomLabel(id);
    require(text.find(n?"2":"II")!=std::string::npos,"numeral style reaches real label: "+text+" format="+std::to_string(format)+" compact="+std::to_string(collapsed));require((text.find('*')!=std::string::npos)==excited,"excited state independent of oxidation");
    auto parsed=CatalyticMetal::read(sample.doc,id);require(parsed.numerals==n&&parsed.format==format&&parsed.excited==excited,"settings remembered");
    if(!collapsed)require(CatalyticMetal::fold(sample.doc,id,false),"right-click collapse model");require(sample.doc.stats().aliveAtoms==1,"compact one visible anchor");
    require(CatalyticMetal::fold(sample.doc,id,true),"expand compact fragment");require(sample.doc.stats().aliveAtoms==4&&sample.doc.stats().aliveBonds==3&&sample.doc.atoms().alive(id)->element==46,"real metal and three ligands restored at same anchor");
    auto runs=studioatom::runs(sample.doc,id);bool star=false;for(auto r:runs)if(r.utf8.find('*')!=std::string::npos)star=(r.flags&kSuperscript)!=0;require(!excited||star,"star remains superscript after expansion");++cases;
 }
 Session demo;demo.doc.setDefaultFont("Arial");demo.doc.setDefaultBondLength(22);studioio::Page pg;pg.x=pg.y=0;pg.width=650;pg.height=650;pg.store(demo.doc);CatalyticMetal cfg;cfg.excited=true;std::vector<ObjectId> nodes;for(int i=0;i<6;++i)nodes.push_back(cfg.apply(demo.doc,kInvalidObjectId,Vec2(i*70,0)));std::vector<ObjectRef> made;
 require(arrange(demo.doc,nodes,Vec2(300,300),185,140,true,&made,true,.3).ok(),"inherit rotated ellipse");
 for(auto ref:made){arrows::ArrowParams p;bool valid=false;arrows::readArrow(demo.doc,ref.id,&p,&valid);require(valid&&p.route.size()>80,"ellipse retains smooth route");for(auto q:arrows::routedPoints(p)){auto v=q-Vec2(300,300);double x=v.x*std::cos(.3)+v.y*std::sin(.3),y=-v.x*std::sin(.3)+v.y*std::cos(.3);require(std::abs(x*x/(185*185)+y*y/(140*140)-1)<1e-8,"all spans on exact same inherited ellipse");}}
 // Ordinary crossing arrows retain their endpoints; only the later path changes.
 Document crossing;auto a=arrows::resolvePreset(58,Vec2(40,130),Vec2(230,130),.6);a.arcSagitta=-65;ObjectId first,later;arrows::addArrow(crossing,a,.6,&first);auto b=arrows::resolvePreset(58,Vec2(130,30),Vec2(130,230),.6);b.arcSagitta=65;arrows::addArrow(crossing,b,.6,&later);arrows::ArrowParams old;bool valid=false;arrows::readArrow(crossing,first,&old,&valid);auto encoded=arrows::encodeArrowParams(old);require(studio::arrow_crossings::update(crossing).ok(),"crossing operation");arrows::ArrowParams smoothed;arrows::readArrow(crossing,later,&smoothed,&valid);require(smoothed.route.size()>60&&length(smoothed.begin-b.begin)<1e-8&&length(smoothed.end-b.end)<1e-8,"newer crossing arrow becomes editable S curve with fixed endpoints");arrows::readArrow(crossing,first,&old,&valid);require(arrows::encodeArrowParams(old)==encoded,"earlier arrow unchanged");
 for(const auto& path:{std::string("cdxml"),std::string("r62doc")}){auto name=dir+"/smooth-catalytic-demo."+path;require(demo.save(name,path=="cdxml").ok(),"save "+path);Session reopened;require(reopened.open(name).ok(),"reopen "+path);int count=0;for(const auto& x:reopened.doc.atoms().records())if(x.isAlive()&&reopened.doc.extensions(ObjectRef(ObjectKind::Atom,x.id)).findValue(CatalyticMetal::attr("Metal"))){require(CatalyticMetal::read(reopened.doc,x.id).excited,"excited state survives file");++count;}require(count==6,"all six metal settings survive");}
 CycleFields dialog;dialog.cycle=true;dialog.values={"6","185","140"};dialog.metal=cfg;require(dialog.rebuild()&&dialog.cyclePreview&&dialog.metalPreview,"both live previews use real structures");dialog.values[1]="bad";require(!dialog.rebuild(),"invalid preview input rejected");
 app.s.cancel();app.s.doc=demo.doc;app.s.history.clear();app.s.selected.clear();app.s.refresh();app.s.fit();app.invalidate();app.screenshot(dir+"/smooth-catalytic-demo.png",false,false);
 std::ofstream(dir+"/catalytic-v2-checks.json")<<"{\"metal_format_cases\":"<<cases<<",\"real_fragment_fold_expand\":true,\"excited_state\":true,\"exact_inherited_ellipse\":true,\"dual_previews\":true,\"later_arrow_S_transition\":true,\"earlier_arrow_unchanged\":true,\"native_and_cdxml\":true}";
}
